CREATE TABLE t1(i INTEGER PRIMARY KEY,a TEXT UNIQUE,b BLOB NOT NULL,c TEXT UNIQUE);CREATE TABLE n(i INTEGER PRIMARY KEY);WITH RECURSIVE x(i)AS(VALUES(1)UNION ALL SELECT i+1 FROM x WHERE i<498)INSERT INTO n SELECT i FROM x;INSERT INTO t1 SELECT i,'a'||i,zeroblob(100+i%50),'b'||i FROM n WHERE i<=449;DELETE FROM t1 WHERE i%10=3;INSERT INTO t1 SELECT i,'x'||i,zeroblob(120+i%60),'y'||i FROM n WHERE i>449 OR i%10=3;